      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Personalized or custom-made handbags are not eligible for return or exchange for change of mind, size preference, or customer typos. However, if a personalized bag arrives damaged, defective, or incorrect, you can contact support within 7 days of delivery with photos for a replacement, exchange, or refund."
      }
