      "name": "What is the return window for non-custom PreAureum handbags?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Eligible unused, unworn, non-custom items in their original condition with all original packaging, tags, and accessories may be requested for return or exchange within 30 days of delivery."
      }
    },
