      "@type": "Question",
      "name": "Where should I mail an approved return package?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Do not send any item back to the sender address, manufacturer address, or the address shown on the shipping label unless instructed. Wait for PreAureum support to approve your return request and provide the official return shipping address."
      }
    },
    {
      "@type": "Question",
      "name": "How long does an approved refund take to appear on my account?",
      "acceptedAnswer": {
        "@type": "Answer",
